-- Exact two-crop supersession. Eight externally verified R2 objects; preserve all previous assets/objects.
begin;
set local lock_timeout='1s';
set local statement_timeout='5s';
lock table catalog.assets,catalog.catalogue_version_assets in share row exclusive mode;
lock table catalog.sets,catalog.catalogue_versions,catalog.catalogue_version_sets,ingest.sources,catalog.card_variants,catalog.card_printings in share mode;
do $publish$ declare actual_links jsonb;affected bigint;begin
if (select jsonb_build_object('id',s.id,'set_code',s.set_code,'game_code',s.game_code,'native_name',s.native_name,'deprecated_at',s.deprecated_at,'language_code',s.language_code,'provider_set_code',s.provider_set_code,'english_display_name',s.english_display_name) from catalog.sets s where s.id='7dbeff79-cfb7-4ac8-8a4f-d7c73a523349'::uuid) is distinct from '{"id":"7dbeff79-cfb7-4ac8-8a4f-d7c73a523349","set_code":"LL","game_code":"pokemon","native_name":"ロストリンク","deprecated_at":null,"language_code":"ja","provider_set_code":"LL","english_display_name":"Lost Link"}'::jsonb then raise exception 'Exact Japanese set identity changed'; end if;
if (select jsonb_build_object('id',s.id,'set_code',s.set_code,'game_code',s.game_code,'native_name',s.native_name,'deprecated_at',s.deprecated_at,'language_code',s.language_code,'provider_set_code',s.provider_set_code,'english_display_name',s.english_display_name) from catalog.sets s where s.id='e8e16a23-fc7a-4ec8-abfe-b74448fa5f27'::uuid) is distinct from '{"id":"e8e16a23-fc7a-4ec8-abfe-b74448fa5f27","set_code":"L1b","game_code":"pokemon","native_name":"ソウルシルバーコレクション","deprecated_at":null,"language_code":"ja","provider_set_code":"L1b","english_display_name":"SoulSilver Collection"}'::jsonb then raise exception 'Exact Japanese set identity changed'; end if;
 if not exists(select 1 from ingest.sources where id='a23954d2-49ca-4f2e-8cee-ed628e179006'::uuid and code='stackr_manual') then raise exception 'Source changed'; end if;
 if (select coalesce(jsonb_agg(jsonb_build_object('set_id',s.set_id,'catalogue_version_id',s.catalogue_version_id,'language_code',s.language_code) order by s.set_id,s.catalogue_version_id),'[]'::jsonb) from api.catalogue_sets s where s.set_id in ('e8e16a23-fc7a-4ec8-abfe-b74448fa5f27'::uuid,'7dbeff79-cfb7-4ac8-8a4f-d7c73a523349'::uuid)) is distinct from '[{"set_id":"7dbeff79-cfb7-4ac8-8a4f-d7c73a523349","language_code":"ja","catalogue_version_id":"1a23b7a7-c50e-4601-9180-a25c950d27ea"},{"set_id":"e8e16a23-fc7a-4ec8-abfe-b74448fa5f27","language_code":"ja","catalogue_version_id":"1a23b7a7-c50e-4601-9180-a25c950d27ea"}]'::jsonb then raise exception 'Complete published memberships changed'; end if;
