delete from catalog.catalogue_version_assets cva using jsonb_array_elements('[{"set_id":"7dbeff79-cfb7-4ac8-8a4f-d7c73a523349","asset_id":"f7fc344c-9f7c-4298-af9d-1903b1bc8e5d","asset_type":"set_logo","created_at":"2026-09-27T16:56:59.630767+00:00","variant_id":null,"printing_id":null,"language_code":"ja","catalogue_version_id":"1a23b7a7-c50e-4601-9180-a25c950d27ea"},{"set_id":"e8e16a23-fc7a-4ec8-abfe-b74448fa5f27","asset_id":"cabf15f1-addc-47e0-9aef-09e2f57bf476","asset_type":"set_logo","created_at":"2026-09-27T16:56:59.630767+00:00","variant_id":null,"printing_id":null,"language_code":"ja","catalogue_version_id":"1a23b7a7-c50e-4601-9180-a25c950d27ea"}]'::jsonb) wanted(item) where cva.catalogue_version_id=(item->>'catalogue_version_id')::uuid and cva.asset_id=(item->>'asset_id')::uuid;
